const listReviewTallies = `-- name: ListReviewTallies :many
WITH released AS (
    SELECT
        v.agent_id,
        COUNT(DISTINCT v.round_id)::int AS rounds
    FROM
        reviews v
    WHERE
        v.released_at IS NOT NULL
    GROUP BY
        v.agent_id
),
concluded AS (
    SELECT DISTINCT ON (v.agent_id)
        v.agent_id,
        v.verdict,
        n.snapshot_sha
    FROM
        reviews v
        JOIN review_rounds n ON n.id = v.round_id
    WHERE
        v.released_at IS NOT NULL
        AND v.verdict IN ('approved', 'changes_requested')
    ORDER BY
        v.agent_id,
        n.ordinal DESC,
        v.released_at DESC
)
SELECT
    r.agent_id,
    r.rounds,
    c.verdict,
    c.snapshot_sha
FROM
    released r
    LEFT JOIN concluded c ON c.agent_id = r.agent_id
`

type ListReviewTalliesRow struct {
	AgentID     string
	Rounds      int32
	Verdict     NullReviewVerdict
	SnapshotSha *string
}

