const listUnlandedReviewRounds = `-- name: ListUnlandedReviewRounds :many
SELECT
    r.agent_id,
    r.ordinal,
    r.base_sha,
    r.snapshot_sha,
    m.merged_at
FROM
    review_rounds r
    JOIN agents a ON a.id = r.agent_id
    LEFT JOIN LATERAL (
        SELECT
            p.merged_at
        FROM
            agent_pull_requests o
            JOIN pull_requests p ON p.id = o.pull_request_id
        WHERE
            o.agent_id = r.agent_id
            AND p.merged_at IS NOT NULL
        ORDER BY
            p.merged_at DESC
        LIMIT 1) m ON TRUE
WHERE
    r.landed_at IS NULL
    AND a.archived_at IS NULL
    AND EXISTS (
        SELECT
            1
        FROM
            reviews v
        WHERE
            v.round_id = r.id
            AND v.released_at IS NOT NULL)
ORDER BY
    r.agent_id,
    r.ordinal DESC
`

